import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"MUSE: A Multi-agent Framework for Unconstrained Story Envisioning via Closed-Loop Cognitive Orchestration","description":"","frontmatter":{"title":"MUSE: A Multi-agent Framework for Unconstrained Story Envisioning via Closed-Loop Cognitive Orchestration","arxiv":"2602.03028","date":"2026-02-03","authors":"Wenzhang Sun, Zhenyu Wang, Zhangchi Hu, Chunfeng Wang, Hao Li, Wei Chen","categories":"cs.CV","topics":"智能体视频生成, 闭环编排, 有声故事片","outline":[2,2]},"headers":[],"relativePath":"papers/2602.03028.md","filePath":"papers/2602.03028.md","lastUpdated":null}'),e={name:"papers/2602.03028.md"};function l(i,s,r,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="muse-a-multi-agent-framework-for-unconstrained-story-envisioning-via-closed-loop-cognitive-orchestration" tabindex="-1">MUSE: A Multi-agent Framework for Unconstrained Story Envisioning via Closed-Loop Cognitive Orchestration <a class="header-anchor" href="#muse-a-multi-agent-framework-for-unconstrained-story-envisioning-via-closed-loop-cognitive-orchestration" aria-label="Permalink to &quot;MUSE: A Multi-agent Framework for Unconstrained Story Envisioning via Closed-Loop Cognitive Orchestration&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2602.03028" target="_blank" rel="noreferrer">2602.03028</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-02-03</td></tr><tr><td><strong>作者</strong></td><td>Wenzhang Sun, Zhenyu Wang, Zhangchi Hu, Chunfeng Wang, Hao Li, Wei Chen（理想汽车、中国科学技术大学）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把故事成片做成 plan-execute-verify-revise 的闭环：规划器出可执行控制、执行器调生成工具、校验器给结构化批评、修订器定点改写，全程共享一份状态 memory，并配一个自训的可控音色模型给角色配音。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><p>本页依据 <code>arxiv.org/html/2602.03028v1</code> 全文撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>从一句故事梗概到一段有画面有声音的成片，中间要做的决定远多于&quot;调用哪个生成模型&quot;。谁是主角、他长什么样、他的声音是什么样、这一镜他站在画面哪个位置、这一镜和上一镜怎么接。开环流水线的做法是让 LLM 一次性把这些决定全写出来，然后逐条执行。这个设计的失败模式很固定：某一步的输出不符合计划（人物位置错了、身份漂了），后面所有步骤都建立在错误的基础上，而系统没有任何环节会发现。</p><p>MUSE 的立场是把&quot;检查&quot;提升为流程里的一等公民。生成之后必须有一个结构化的校验步骤，校验不过就定点修订，改完再校验，最多迭代若干次。这条闭环让错误在本地被吸收，而不是沿着流水线传播。</p><p>第二件被认真对待的事是声音。故事片的角色一致性不只是脸，还有音色。MUSE 训了一个可控音色模型 VTS，在前期就给每个角色定一个&quot;声音锚&quot;，与视觉的身份锚并列。把音色纳入一致性管理，是这篇论文相对同类工作的一个实质区别。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>MovieAgent</strong>：ViStoryBench 上 Cross-CIDS 0.299，是所有对照里最强的一个；MUSEBench 的脚本三项 SER/NSR/CES 为 3.50/2.53/3.73。它的角色一致性做得不错，弱点在叙事结构评分（NSR 2.53）明显低于视觉项。</p><p><strong>AnimDirector</strong>：Cross-CIDS 0.288；脚本项 3.53/1.73/1.87。SER 高而 NSR、CES 很低，说明它能写出像样的单句描述，但故事层面的组织能力弱。</p><p><strong>Vlogger</strong>：Cross-CIDS 0.259。<strong>MMStoryAgent</strong>：Cross-CIDS 0.238，脚本项 2.89/1.59/2.28。<strong>V-GOT</strong>：Cross-CIDS 0.232，脚本项 2.23/1.97/2.2，是对照中最低的一档。</p><p>这几个系统的共性缺口是流程开环。它们都有&quot;规划&quot;，但没有&quot;验证规划是否被执行到位&quot;。一旦生成模型没有听话（bbox 里该站人的地方是空的、角色换了张脸），系统不会知道，也就没有修订的入口。另一个共性缺口是模态覆盖：视觉一致性被反复优化，音色几乎没有被纳入任何一致性机制，角色在不同镜头里可以是完全不同的声音。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个可观察的现象出发：生成模型对复杂指令的服从率不高，同一条 prompt 采样多次，有的对有的错。这意味着单次采样的期望质量低，但<strong>采样分布里存在好样本</strong>。要利用这一点，系统需要一个能判断&quot;这次对不对&quot;的组件。</p><p>判断需要依据。自由文本的批评难以驱动修订，因为不知道该改哪里。所以校验的输出必须结构化：哪个约束被违反、违反到什么程度。有了结构化批评，修订就可以是定点的，只改被指出的部分而不是重新生成整个镜头。</p><p>接着是修订的终止条件。反复修订可能来回震荡，需要一个停止规则。最简单可行的是设迭代上限并保留过程中评分最高的一版。</p><p>最后是模态。视觉的身份锚已经是标准做法，把同样的逻辑套到音色上是自然的推广：角色在前期被分配一个声音锚，后续所有台词都以它为条件。这要求一个能接受音色条件的 TTS，市面模型的可控性不够，于是作者自己训了一个。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>生成模型的服从率不够高，但它的采样分布里有好样本；只要能结构化地判断&quot;这次哪里不对&quot;，就能把修订变成定点操作，把整条流水线从开环变成闭环。角色一致性应当在前期一次性锚定并跨模态覆盖，视觉锚和音色锚都在故事开始前就固定下来。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>闭环的四个角色</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Φ</span></span></span></span> 把当前状态映射成可执行的控制指令；Agent 执行控制、调用生成工具；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 对产出做结构化校验；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ω</span></span></span></span> 依据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 的批评做定点修订。四者共享一份状态 memory <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0097em;">H</span></span></span></span>，所有中间产物与批评历史都写在里面。</p><p><strong>三个阶段</strong>：</p><ul><li><strong>Pre-production</strong>：身份锚定（确定每个角色的视觉参考）与 VTS 声音锚定（确定每个角色的音色）。</li><li><strong>Production</strong>：动态路由决定这一镜该调哪条工具链；bbox 布局给出主体在画面中的位置；几何护栏约束布局的合法性。</li><li><strong>Post-production</strong>：时序合成，第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 段视频以前一段的尾部 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Tail</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 为条件，保证接缝连续。</li></ul><p><strong>后端与超参</strong>：LLM 用 Gemini 2.5 Pro，规划时 temperature 0.7、批评时 0.2；图像用 Flux.2-Dev，guidance 3.5、28 步；视频用 Wan2.2-I2V-A14B；语音用自训的 VTS（基于 Qwen3-1.7B 加 XY-Tokenizer）。硬件为 H200。闭环最多迭代 5 次，取过程中得分最高的一版。</p><p><strong>VTS 训练</strong>：10 万小时无条件音频预训练，加 2 万小时由 Gemini 标注的数据做指令微调。</p><p><strong>一个具体例子</strong>：输入&quot;一个退休渔夫在暴风雨夜找回走失的狗&quot;。Pre-production 给渔夫定一张视觉参考图和一个偏低沉沙哑的音色锚。Production 阶段第 3 镜的控制指令是&quot;渔夫在画面左三分之一处，手持马灯，中景&quot;，Agent 生成后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 检查 bbox 内是否有主体、身份是否与参考一致，若发现马灯缺失就给出结构化批评，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ω</span></span></span></span> 只重做这一镜的道具部分。Post-production 把第 3 镜以第 2 镜尾部为条件续接，并按音色锚合成台词。</p><p><strong>评测</strong>：自建 MUSEBench 含 30 条 prompt，覆盖 5 类题材、1 到 3 个主角，为无参考评测；另在 ViStoryBench 的 80 个故事上做对照。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>闭环可以写成状态上的迭代映射。记第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 轮的共享状态为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，则</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Φ</span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Agent</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Ψ</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Ω</span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是可执行控制、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是产出、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是结构化批评。作者把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ω</span></span></span></span> 描述为定点修订，理想情形下迭代收敛到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 判定合格的不动点。</p><p>实现层面的终止规则与这个理想有距离：迭代上限为 5，最终输出取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">max</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">score</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。这使得实际算法等价于一个 <strong>best-of-5 选择器</strong>，其中打分与生成条件都由同一套 LLM 后端提供。收敛性因此不来自不动点性质，而来自采样分布中最优样本随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 的增长——这是一条与&quot;认知闭环&quot;不同的机制解释，§11 会给出区分二者的实验。</p><p>时序合成的条件化写作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">Tail</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">))</span></span></span></span>，即每段视频以前一段尾部为条件。这条链式依赖保证了接缝连续，同时意味着误差沿镜头序列单向传播，前期镜头的质量对整片影响更大。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：闭环编排能否提升角色一致性。</strong> ViStoryBench 表 3 首列 Cross-CIDS：MUSE 0.412，MovieAgent 0.299，AnimDirector 0.288，Vlogger 0.259，MMStoryAgent 0.238，V-GOT 0.232。MUSE 相对最强对照高出 0.113 个绝对点，是全文差距最大的一项。作者同时承认，由于系统会重写用户 prompt，prompt 对齐类指标相对下降，这个取舍被明确写进了正文。</p><p><strong>问题二：脚本质量是否同步提升。</strong> MUSEBench 表 2 的脚本三项 SER/NSR/CES：MUSE 3.70/3.67/3.93，MovieAgent 3.50/2.53/3.73，AnimDirector 3.53/1.73/1.87，MMStoryAgent 2.89/1.59/2.28，V-GOT 2.23/1.97/2.2。MUSE 在 SER 上的领先很小（3.70 对 3.53），在 NSR 上的领先很大（3.67 对 2.53）。叙事结构是闭环编排收益最集中的地方。</p><p><strong>问题三：规划与反馈各自贡献多少。</strong> 表 4 首列：Basemodel 0.609，加规划 0.697，加反馈 0.671，完整 0.714；末列：0.619 → 0.791 → 0.637 → 0.857。两列都呈现同一个模式，单独加反馈的收益小于单独加规划，而两者合起来最高。这与直觉一致：没有结构化计划时，校验器缺少可对照的约束，批评就无从谈起。音频侧的 Age/Prosody 四档为 2.79/1.54、2.81/1.60、2.97/1.70、3.05/1.75，单调上升但幅度小。</p><p><strong>问题四：自动评测能不能信。</strong> 这是全文最该被引用的一张表。表 5 报告自动评分与人工评分的 Pearson 相关系数，样本 140 条：逻辑一致性 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.64</span></span></span></span>，视觉保真 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.74</span></span></span></span>，音色质量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.49</span></span></span></span>。视觉一项算可用，逻辑一项勉强，音色一项 0.49 属于弱相关，意味着表 4 里音频列的那些小幅提升（1.54 → 1.75）在人类听感上未必存在。作者主动报告了这组校准数据，这一点比多数同类工作做得好，也让读者有依据去打折它自己的结论。</p><p><strong>问题五：VTS 是否值得自训。</strong> 表 6 在 400 条真值续写上比较 Age/Emotion/Prosody/Clarity：CosyVoice2 3.7/2.02/2.08/4.38，F5-TTS 3.76/2.1/2.2/4.92，VTS 3.97/2.23/2.44/4.59。VTS 在前三项领先，Clarity 一项 4.59 低于 F5-TTS 的 4.92。可控性换清晰度的取舍是明确的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：把生成流水线从开环改成 plan-execute-verify-revise 闭环，收益最集中的地方是叙事结构（NSR 3.67 对 2.53），不是单句质量。结构化批评是修订可行的前提，单独加反馈不如单独加规划，因为没有计划就没有可对照的约束。角色一致性应当跨模态锚定，音色和脸一样需要在前期定死。作者报告了自动评分与人评的相关系数（0.74/0.64/0.49），音色一项的弱相关直接限定了音频结论的可信度。实现里的&quot;最多 5 次迭代取最高分&quot;使系统等价于 best-of-5 选择器，闭环的收益需要与重采样的收益分开测量。</p><p><strong>3 句版</strong>：MUSE 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Φ/Ψ/Ω</span></span></span></span> 三件套加共享状态把故事成片做成闭环，三阶段覆盖身份与音色锚定、布局护栏、时序续接。ViStoryBench Cross-CIDS 0.412 对最强对照 0.299，MUSEBench 脚本项全面领先。自动评测的人机相关系数被诚实报出，其中音色 0.49 说明该维度的结论应当保留。</p><p><strong>1 句版</strong>：让生成流水线自带一个结构化的校验-修订环，故事层面的组织质量提升最明显，而这个环的收益必须与单纯多采样几次区分开。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>校验器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 的判断与人类判断足够对齐</strong>。整个闭环的价值完全建立在&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 说不好的确实不好、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 说好的确实好&quot;之上。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 有系统性偏差，闭环就不是在提升质量，而是在朝着这个偏差做定向优化，迭代次数越多偏离越远。这条假设失效的代价是全部贡献塌掉：所谓的认知编排会退化成对一个坏目标的过拟合。</p><p>论文为它提供了直接证据，而且是负面偏多的证据。表 5 的人机相关系数：视觉保真 0.74 尚可，逻辑一致性 0.64 属于中等，音色质量 0.49 属于弱相关。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.49</span></span></span></span> 意味着自动分只能解释人评方差的约四分之一，用它去驱动最多 5 轮修订并挑最高分，在音频维度上接近于按噪声选择。</p><p>风险还有一层放大：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 与规划器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Φ</span></span></span></span> 用的是同一个 Gemini 2.5 Pro 后端（仅 temperature 不同），批评者和被批评者共享先验，系统性盲点不会被发现。更关键的是，若最终报告的自动指标与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 的打分来自同一模型族，那么&quot;取 5 次中最高分&quot;就是在被报告的指标上直接做选择，这在方法论上等价于用测试指标做模型选择。作者报告的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 值给了读者打折的依据，但没有做&quot;换一个独立评审模型重测&quot;这一步。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可完成，目标是分离闭环与重采样这两种解释：</p><ol><li>固定后端与所有超参，实现三个配置：(a) 单次生成；(b) 无计划无批评的 best-of-5，即同一条 prompt 采 5 次，用与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 相同的打分器选最高分；(c) 完整闭环（结构化批评加定点修订，最多 5 轮）。</li><li>用 30 条 MUSEBench 规模的 prompt 跑三个配置，每条重复 3 个随机种子。</li><li>测两组分：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 自动分，以及不少于 20 人的人工成对偏好。</li><li>判据：若 (c) 相对 (b) 的提升在自动分上明显、在人工偏好上消失，则闭环的收益主要是对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ψ</span></span></span></span> 的过拟合；若两者都提升，则结构化修订确实带来了重采样之外的东西。</li></ol><p>三个配置共享同一套后端，因此这个实验不需要复现 VTS 或任何训练。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是给出对结果的<strong>替代解释</strong>：MUSE 的领先可能主要来自&quot;生成 5 次挑最好的一次&quot;，而不是来自认知编排。这个解释有三条支撑。其一，实现细节写明最多迭代 5 次并取最高分，这在形式上就是 best-of-5。其二，表 4 里单独加反馈只把首列从 0.609 提到 0.671，低于单独加规划的 0.697，说明&quot;批评-修订&quot;这一环本身的边际贡献并不突出。其三，选择所用的打分器与报告所用的指标共享 LLM 后端，选择偏差会直接体现在报告值上。</p><p>对应的可执行反例就是 §10 里的配置 (b)：一个没有任何计划结构、没有结构化批评、只是重复采样并用同一打分器挑最优的<strong>平凡基线</strong>。若它的 Cross-CIDS 接近 0.412，那么表 3 的 0.113 个绝对点就不能归因于闭环编排。论文没有报告这个基线，这是当前实验设计里最大的缺口。</p><p>第二重攻击针对音频结论。表 5 已经给出音色维度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.49</span></span></span></span>，因此表 4 里 Prosody 从 1.54 到 1.75 的提升、以及表 6 中 VTS 对 F5-TTS 的领先，都应当补一组盲测人工听辨来确认；同时 VTS 的 Clarity 4.59 低于 F5-TTS 的 4.92，在实际配音场景里清晰度往往优先于音色可控性，这个取舍方向未必符合用户偏好。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动 idea 的局限是：闭环把一个未经校准的评判器放在了优化回路里，而校准数据（0.74 / 0.64 / 0.49）恰恰显示不同维度的可信度差了一倍以上。当前系统对所有维度一视同仁地迭代修订，等于在最不可信的维度上花了同样多的采样预算。</p><p>可借鉴的相邻工具来自不确定性量化与选择性预测：把校验器改造成<strong>带弃权的评判器</strong>，先在人工标注集上估计它在每个维度上的可靠区间，当某次判断落在低置信区域时不触发修订，而是标记出来交给人工或换一个独立评审模型复判。修订预算按维度可靠度分配，而不是平均分配。这把&quot;迭代几次&quot;从超参变成了由校准曲线决定的量。</p><p>第一个实验：在 140 条已有人评的样本上，为每个维度拟合自动分到人评的条件分布，得到每个分数区间的可靠度；然后在新一批 prompt 上比较两种预算分配——均匀迭代 5 轮，与按可靠度加权、总采样次数相同的自适应迭代。测同等算力下的人工偏好率。若自适应方案在相同预算下胜出，就说明评判器的校准应当先于编排结构被优化，这对所有把 LLM 当 verifier 的系统都成立，而不只是故事生成。</p>',60)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
